// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";

/**
 * @title CounterV2
 * @dev UUPS upgradeable counter contract - Version 2 with additional features
 */
contract CounterV2 is Initializable, UUPSUpgradeable, OwnableUpgradeable {
    uint256 public count;
    uint256 public step;

    event CountIncremented(uint256 newCount, uint256 step);
    event CountDecremented(uint256 newCount, uint256 step);
    event StepChanged(uint256 oldStep, uint256 newStep);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address initialOwner) public initializer {
        __Ownable_init(initialOwner);
        __UUPSUpgradeable_init();
        count = 0;
        step = 1;
    }

    function initializeV2(uint256 _step) public reinitializer(2) {
        step = _step;
    }

    function increment() external {
        count += step;
        emit CountIncremented(count, step);
    }

    function decrement() external {
        require(count >= step, "Counter: count would go below zero");
        count -= step;
        emit CountDecremented(count, step);
    }

    function setStep(uint256 _step) external onlyOwner {
        require(_step > 0, "Counter: step must be greater than zero");
        uint256 oldStep = step;
        step = _step;
        emit StepChanged(oldStep, _step);
    }

    function getCount() external view returns (uint256) {
        return count;
    }

    function getStep() external view returns (uint256) {
        return step;
    }

    function reset() external onlyOwner {
        count = 0;
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}
}

